import { test, expect } from '@playwright/test';

test.describe('Error Messages Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display error message for required field', async ({ page }) => {
    await page.getByLabel('Username').fill(''); // Assuming there's a label for the username field
    await page.getByRole('button', { name: 'Submit' }).click(); // Assuming there's a submit button

    const errorMessage = await page.getByText('This field is required.'); // Replace with actual error message
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toHaveAttribute('role', 'alert'); // Ensure it's accessible
  });

  test('should display error message for invalid email', async ({ page }) => {
    await page.getByLabel('Email').fill('invalid-email'); // Assuming there's a label for the email field
    await page.getByRole('button', { name: 'Submit' }).click(); // Assuming there's a submit button

    const errorMessage = await page.getByText('Please enter a valid email address.'); // Replace with actual error message
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toHaveAttribute('role', 'alert'); // Ensure it's accessible
  });
});
